<script>
  import { randomString } from '@splendidlabz/utils/dom'
  import { useActions } from '../../actions/use-actions'
  import { init } from '../../utils'
  import FieldMeta from './FieldMeta.svelte'

  /**
   * @import { Snippet } from 'svelte'
   */

  /**
   * @typedef {object} TextInputProps
   * @property {string} name
   * @property {string} [value]
   * @property {HTMLInputElement | null} [ref]
   * @property {string} [class]
   * @property {string} [style]
   * @property {string} [labelClass]
   * @property {string} [hintClass]
   * @property {string} [errorClass]
   * @property {string} [inputGroupClass]
   * @property {string} [fieldClass]
   * @property {Snippet} [before] Content before the input
   * @property {Snippet} [after] Content after the input
   * @property {Snippet} [children]
   * @property {string} [id]
   * @property {'text' | 'email' | 'password' | 'search' | 'url' | 'tel'} [type]
   * @property {string} [label]
   * @property {boolean} [labelVisible]
   * @property {string | null} [hint]
   * @property {string | null} [error]
   * @property {boolean | null} [disabled]
   * @property {boolean | null} [readonly]
   * @property {{ fn: Function, props?: any }[]} [actions] Actions run on the input
   */

  /** @type {TextInputProps & Record<string, any>} */
  let {
    value = $bindable(''),
    ref = $bindable(null),
    // Classes
    class: klass,
    style,
    labelClass,
    hintClass,
    errorClass,
    inputGroupClass,
    fieldClass,
    // Slots
    before,
    after,
    children,
    // Options and props
    id = randomString(8),
    type = 'text',
    name,
    label = '',
    labelVisible = true,
    hint = null,
    error = null,
    disabled = null,
    readonly = null,
    actions = [], // Might not need this anymore in S5.
    ...rest
  } = $props()

  // For this binding, does it send upwards?? Need testing

  // IDs for aria-describedby
  const hintId = $derived(hint ? id + '-hint' : '')
  const errorId = $derived(id + '-error')
  const describedBy = $derived(`${hintId} ${errorId}`.trim() || null)

  // ========================================
  // Check for errors
  // ========================================
  // Other possible types: date, number, time, week, file, image, month, number, radio, color
  const SUPPORTED_TYPES = ['text', 'email', 'password', 'search', 'url', 'tel']
  init(() => {
    if (!name) throw new Error('TextInput requires a name')
    if (!SUPPORTED_TYPES.includes(type))
      throw new Error(`Invalid type: ${type}`)
  })
</script>

<!-- Snippets -->
{#snippet input()}
  <input
    {...rest}
    bind:this={ref}
    {id}
    {name}
    class="input {fieldClass}"
    {...{ type }}
    aria-describedby={describedBy}
    aria-invalid={error ? 'true' : null}
    aria-label={!labelVisible && label ? label : null}
    {disabled}
    {readonly}
    bind:value
    use:useActions={actions}
  />
{/snippet}

<!-- Output -->
<div
  {style}
  class="input-container text-input text-field {klass}"
  class:disabled
  class:readonly
>
  <FieldMeta
    {id}
    {error}
    {errorClass}
    {hint}
    {hintClass}
    {label}
    {labelClass}
    {labelVisible}
  />

  {#if before || after}
    <div class="input-group {inputGroupClass}">
      {#if before}
        {@render before()}
        <div class="divider-vertical"></div>
      {/if}

      {@render input()}

      {#if after}
        <div class="divider-vertical"></div>
        {@render after()}
      {/if}
    </div>
  {:else}
    {@render input()}
  {/if}
</div>
